import os,glob,re,json

def load():
    d=os.environ.get('RLM_SESSION_DIR', '')
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G=load()
print("Keys:", sorted(G.keys()))
for k in sorted(G):
    print(f"{k}: {G[k]}")

# Extract the demo input/output pairs
demo_in = None
demo_out = None
test_in = None

for k,v in G.items():
    if "Demo pair 1" in k:
        pass  # Skip demo keys
    elif "Test" in k:
        test_in = v

# Find actual demo input key
demo_key = None
for k in G:
    if "Demo pair" in k and "output" not in k.lower():
        if "_out" not in k:
            demo_key = k
            break

print("\nTest input shape:", len(test_in[0]), len(test_in))

# Check what cells are different between input and output
if demo_key:
    demo_val = G[demo_key]

test_in = G['Test input']
print("Test input dimensions:", len(test_in), "x", len(test_in[0]))

# Find all positions of each color in test input
from collections import Counter
color_counts = Counter()
for r in range(len(test_in)):
    for c in range(len(test_in[r])):
        color_counts[test_in[r][c]] += 1

print(f"\nColor counts in test input:\n{dict(color_counts)}")

# Positions of each color
positions = {}
for r in range(len(test_in)):
    for c in range(len(test_in[r])):
        v = test_in[r][c]
        if v not in positions:
            positions[v] = []
        positions[v].append((r,c))

print("\nPositions by color:")
for color in sorted(positions.keys()):
    print(f"  {color}: {len(positions[color])} cells")
    if len(positions[color]) <= 5:
        print(f"    {positions[color]}")

changes = [(2, 9), (3, 8), (4, 7), (4, 11), (5, 5), (5, 6), (5, 10), 
           (6, 5), (6, 7), (6, 9), (6, 13), (7, 7), (7, 8), (7, 12), 
           (8, 7), (8, 9), (8, 11), (9, 9), (9, 10), (10, 9), (10, 11), (11, 11)]

# Check connectivity - cells are adjacent if they share an edge
def has_neighbor(changes, cell):
    r,c = cell
    for r2,c2 in changes:
        if abs(r-r2) + abs(c-c2) == 1:
            return True
    return False

connected_groups = []
used = set()
for c in changes:
    if c in used:
        continue
    group = [c]
    used.add(c)
    changed = True
    while changed:
        changed = False
        i = 0
        while i < len(group):
            curr = group[i]
            if has_neighbor(changes, curr):
                # Find neighbor that's not in group yet
                found = False
                for r2,c2 in changes:
                    if r2,c2 not in used and abs(curr[0]-r2)+abs(curr[1]-c2)==1:
                        group.append((r2,c2))
                        used.add((r2,c2))
                        found = True
                        break
            if not found:
                changed = True
            i += 1
    if len(group) > 1:
        connected_groups.append(sorted(group))

print(f"Number of connected groups (>1 cell): {len(connected_groups)}")
for i, g in enumerate(connected_groups):
    print(f"Group {i+1}: {sorted(g)} - size {len(g)}")

# Also check if all 22 cells form one big connected component
all_connected = True
for c in changes:
    if not has_neighbor(changes, c):
        # Has no direct neighbor in changes
        pass

test_in = G['Test input']
print(f"Test input shape: {len(test_in)}x{len(test_in[0])}")

# Find all positions of 2s
pos_2 = []
for r in range(len(test_in)):
    for c in range(len(test_in[r])):
        if test_in[r][c] == 2:
            pos_2.append((r,c))

print(f"\nPositions of 2s: {pos_2}")

# These are the "marker" positions. Now let's see which 0s are near them
# For a reasonable selection, 0s within say 10 Manhattan distance might be candidates

from collections import defaultdict
zeros_by_distance = defaultdict(list)

for r,c in pos_2:
    for dr in range(-10, 11):
        for dc in range(-10, 11):
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(test_in) and 0 <= nc < len(test_in[nr]):
                if test_in[nr][nc] == 0:
                    dist = abs(dr) + abs(dc)
                    zeros_by_distance[dist].append((nr, nc))

print("\nZeros at each distance from nearest 2:")
for d in sorted(zeros_by_distance.keys())[:10]:
    print(f"  Dist={d}: {len(zeros_by_distance[d])} zeros")

# Let's visualize where the 2s are relative to the grid
H, W = len(test_in), len(test_in[0])
visual = [['.' for _ in range(W)] for _ in range(H)]

for r,c in pos_2:
    visual[r][c] = '2'

for r in range(min(10, H)):
    print(' '.join(visual[r][:W]))

# Try: Fill zeros whose anti-diagonal sum is close to marker sums
test_in = G['Test input']
pos_2 = [(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)]

marker_sums = set(r+c for r,c in pos_2)
print(f"Marker anti-diagonal sums: {sorted(marker_sums)}")

H, W = len(test_in), len(test_in[0])
zeros_by_sum = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            zeros_by_sum[r+c].append((r,c))

# For each zero, find closest marker sum distance
def closest_marker_sum(zero_sum):
    return min(abs(zero_sum - ms) for ms in marker_sums)

close_zeros = []
for s, cells in zeros_by_sum.items():
    dist = closest_marker_sum(s)
    if dist <= 2:
        close_zeros.extend((dist, r, c) for r,c in cells)

print(f"\nZeros within marker-sum distance 2:")
count = {}
for d,r,c in sorted(close_zeros):
    key = f"d={d}"
    count[key] = count.get(key, 0) + 1
for k,v in sorted(count.items()):
    print(f"  {k}: {v} cells")

# Fix: iterate over cells properly
test_in = G['Test input']
pos_2 = [(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)]

marker_sums = sorted(set(r+c for r,c in pos_2))
print(f"Marker sums: {marker_sums}")

H, W = len(test_in), len(test_in[0])
zeros_by_sum = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            zeros_by_sum[r+c].append((r,c))

def fill_range_with_threshold(threshold):
    cells = set()
    for s, cells_in_sum in zeros_by_sum.items():
        if abs(s - marker_sums[1]) <= threshold or abs(s - marker_sums[0]) <= threshold:
            # This sum is within threshold of a marker
            cells.update(cells_in_sum)
    return cells

for t in range(1, 5):
    cells_t = fill_range_with_threshold(t)
    print(f"Threshold |sum-marker_sum|<= {t}: {len(cells_t)} cells")
    if len(cells_t) <= 50:
        print(f"  First: {sorted(cells_t)[:10]}")

# Try thinking about it as: The 2s mark positions, and we need to find cells
# that have similar local structure/neighborhood patterns around them

test_in = G['Test input']
pos_2 = [(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)]
H, W = len(test_in), len(test_in[0])

# Check what value each 2 has in its 3x3 neighborhood (treating out-of-bounds as 0)
def get_neighborhood_signature(r, c):
    sig = []
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W:
                sig.append(test_in[nr][nc])
            else:
                sig.append(0)
    return tuple(sig)

sig_2 = set(get_neighborhood_signature(r,c) for r,c in pos_2)
print(f"Number of unique neighborhood signatures around 2s: {len(sig_2)}")

# Now check zeros with same or similar signatures
similar_zeros = []
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            sig = get_neighborhood_signature(r,c)
            # Check if signature matches any marker's signature exactly
            if sig in sig_2:
                similar_zeros.append((r,c))

print(f"Zeros with identical neighbor signature to any 2: {len(similar_zeros)}")
print("Positions:", sorted(similar_zeros))

# This seems unlikely to match demo output, but let me see...

