test_in = G['Test input']
H, W = len(test_in), len(test_in[0])

from collections import defaultdict
zeros_by_dist = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            min_dist = min(abs(r-mr)+abs(c-mc) for mr,mc in pos_2)
            zeros_by_dist[min_dist].append((r,c))

print("Zeros by minimum Manhattan distance to any marker:")
for d in sorted(zeros_by_dist.keys())[:10]:
    print(f"  Distance {d}: {len(zeros_by_dist[d])} cells")

# Try various thresholds
for threshold in range(1, 6):
    cells = set((r,c) for dist,cells_list in zeros_by_dist.items() 
                for r,c in cells_list if dist <= threshold)
    print(f"\nThreshold <= {threshold}: {len(cells)} cells")

# Try a completely different approach: Check which 0s have no neighbors of value != 0
test_in = G['Test input']
H, W = len(test_in), len(test_in[0])

def count_non_zero_neighbors(r,c):
    count = 0
    for dr in [-1,0,1]:
        for dc in [-1,0,1]:
            if dr==0 and dc==0: continue
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W:
                if test_in[nr][nc] != 0:
                    count += 1
    return count

isolated_zeros = [(r,c) for r in range(H) for c in range(W) 
                  if test_in[r][c] == 0 and count_non_zero_neighbors(r,c) == 0]
print(f"Completely isolated zeros (no non-zero neighbors): {len(isolated_zeros)}")
print("First 10:", sorted(isolated_zeros)[:10])

# Also try: zeros adjacent exactly to one marker
zeros_next_to_one_marker = []
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            marker_count = sum(1 for mr,mc in pos_2 
                              if abs(r-mr)+abs(c-mc) == 1)
            if marker_count >= 1:
                zeros_next_to_one_marker.append((r,c))

print(f"\nZeros next to at least one marker: {len(zeros_next_to_one_marker)}")
print("First 20:", sorted(zeros_next_to_one_marker)[:20])

# Try filling based on main diagonals (r-c = constant)
