H, W = len(test_in), len(test_in[0])

from collections import defaultdict
zeros_by_diff = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            zeros_by_diff[r-c].append((r,c))

marker_diffs = set(r-c for r,c in pos_2)
print(f"Marker main diagonals (r-c): {sorted(marker_diffs)}")

# Fill zeros on these exact diagonals
def build_output_from_diffs(input_grid, target_diffs):
    output = [[input_grid[r][c] for c in range(len(input_grid[0]))] for r in range(len(input_grid))]
    for d in target_diffs:
        for r,c in zeros_by_diff.get(d, []):
            output[r][c] = 8
    return output

result = build_output_from_diffs(test_in, marker_diffs)
print("\nResult with main diagonals matching markers:")
for row in result:
