test_in = G['Test input']
H, W = len(test_in), len(test_in[0])

from collections import defaultdict
zeros_by_sum = defaultdict(list)
zeros_by_diff = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            zeros_by_sum[r+c].append((r,c))
            zeros_by_diff[r-c].append((r,c))

marker_sums = set(r+c for r,c in pos_2)
marker_diffs = set(r-c for r,c in pos_2)

def build_output_combined(input_grid, target_sums=None, target_diffs=None):
    output = [[input_grid[r][c] for c in range(len(input_grid[0]))] for r in range(len(input_grid))]
    if target_sums:
        for s in target_sums:
            for r,c in zeros_by_sum.get(s, []):
                output[r][c] = 8
    if target_diffs:
        for d in target_diffs:
            for r,c in zeros_by_diff.get(d, []):
                output[r][c] = 8
    return output

# Combined: union of both conditions
result = build_output_combined(test_in, marker_sums, marker_diffs)

print("Result with combined conditions:")
count_8s = sum(sum(1 for x in row if x==8) for row in result)
print(f"Total 8s created: {count_8s}")
for row in result:
    print(row)

# Try exact marker sums - fill ALL zeros on anti-diagonals matching marker sums
pos_2 = [(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)]

test_in = G['Test input']
H, W = len(test_in), len(test_in[0])
from collections import defaultdict
zeros_by_sum = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            zeros_by_sum[r+c].append((r,c))

marker_sums = sorted(set(r+c for r,c in pos_2))
print(f"Marker sums: {marker_sums}")

def build_output(input_grid, target_sums):
    output = [[input_grid[r][c] for c in range(len(input_grid[0]))] for r in range(len(input_grid))]
    for s in target_sums:
        for r,c in zeros_by_sum.get(s, []):
            output[r][c] = 8
    return output

result = build_output(test_in, marker_sums)
count = sum(sum(1 for x in row if x==8) for row in result)
print(f"\nTotal 8s on exact marker sums: {count}")
for row in result:
    print(row)

# Find what geometric structure exists in demo
demo_in = G['Demo pair 1 input']

# Look at where non-zeros ARE on the key bands
print("Where are NON-ZERO cells on sums 11, 15, 19?")
from collections import defaultdict
all_c = defaultdict(list)
for r in range(15):
    for c in range(27):
        all_c[r+c].append((r,c))

target_sums = [11, 15, 19]
for s in target_sums:
    nz_cells = [cell for cell in all_c[s] if demo_in[cell[0]][cell[1]] != 0]
    print(f"\nSum {s} non-zeros: {sorted(nz_cells)}")

# Check main diagonal positions of non-zeros on these sums
print("\n\nNon-zero positions by main diagonal:")
nz_by_diff = defaultdict(list)
for s in target_sums:
    for r,c in all_c[s]:
        if demo_in[r][c] != 0:
            nz_by_diff[r-c].append((r,c))
for d in sorted(nz_by_diff.keys()):
    print(f"Diff {d}: {nz_by_diff[d]}")

# Test various rule combinations
pos_2_test = [(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)]
test_in = G['Test input']
H, W = len(test_in), len(test_in[0])
from collections import defaultdict
zeros_by_sum = defaultdict(list)
for r in range(H):
    for c in range(W):
        if test_in[r][c] == 0:
            zeros_by_sum[r+c].append((r,c))

marker_sums = sorted(set(r+c for r,c in pos_2_test))
print(f"Marker sums: {marker_sums}")

# Try different rules
def apply_rule(output_grid, rule_type):
    if rule_type == 'exact_marker':
        # Fill zeros on exact marker sums
        for s in marker_sums:
            for r,c in zeros_by_sum.get(s, []):
                output_grid[r][c] = 8
    elif rule_type == 'marker_range_no_div4':
        # Fill between min/max marker sum, excluding div by 4
        for s in range(marker_sums[0], marker_sums[-1]+1):
            if s % 4 != 0:
                for r,c in zeros_by_sum.get(s, []):
                    output_grid[r][c] = 8
    elif rule_type == 'expanded_marker_range_no_div4':
        # Expand range by ±2 from markers
        low, high = max(0, marker_sums[0]-2), min(40, marker_sums[-1]+2)
        for s in range(low, high+1):
            if s % 4 != 0:
                for r,c in zeros_by_sum.get(s, []):
                    output_grid[r][c] = 8
    return output_grid

def count_eights(grid):
    return sum(sum(1 for x in row if x==8) for row in grid)

# Create copies and apply rules
import copy
result_exact = build_output(copy.deepcopy(test_in), 'exact_marker')
print(f"Exact marker sums: {count_eights(result_exact)} 8s")

result_range = build_output(copy.deepcopy(test_in), 'marker_range_no_div4')
print(f"Marker range [12,14] excl div4: {count_eights(result_range)} 8s")

result_expanded = build_output(copy.deepcopy(test_in), 'expanded_marker_range_no_div4')
print(f"Expanded range excl div4: {count_eights(result_expanded)} 8s")

