def orthogonal_neighbors(r, c, H, W):
    neighs = []
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < H and 0 <= nc < W:
            neighs.append((nr, nc))
    return neighs

